mapper.select:
SELECT EXISTS (
    SELECT 1 FROM org_department
    WHERE code = #{code}
    AND id <> #{excludeId}
)

mapper.update:
UPDATE org_department
SET code = #{request.code}, name = #{request.name}, parent_id = #{request.parentId},
    manager_employee_id = #{request.managerEmployeeId}, sort_order = #{request.sortOrder},
    enabled = #{request.enabled}
WHERE id = #{id}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM org_position
    WHERE department_id = #{departmentId} AND code = #{code}
    AND id <> #{excludeId}
)

mapper.update:
UPDATE org_position
SET code = #{request.code}, name = #{request.name}, enabled = #{request.enabled}
WHERE department_id = #{departmentId} AND id = #{id}
